def summarize(numbers):
    """Return a summary dict for a list of numbers.

    Preserves input order and contents. Count includes duplicates.
    Empty input returns count=0, total=0, mean=None, min=None, max=None.
    """
    if not numbers:
        return {"count": 0, "total": 0, "mean": None, "min": None, "max": None}
    total = sum(numbers)
    count = len(numbers)
    return {
        "count": count,
        "total": total,
        "mean": total / count,
        "min": min(numbers),
        "max": max(numbers),
    }

